{
  "name": "kiwi-agent",
  "displayName": "KiwiAgent",
  "description": "Coding sessions in VS Code with a choice of model engine per session.",
  "version": "0.2.0",
  "publisher": "CoderrAB",
  "icon": "docs/logos/logo-square-transparent-500px.png",
  "galleryBanner": {
    "color": "#1e1e1e",
    "theme": "dark"
  },
  "license": "GPL-3.0-only",
  "repository": {
    "type": "git",
    "url": "https://github.com/jgauffin/kiwi-code-agent.git"
  },
  "homepage": "https://github.com/jgauffin/kiwi-code-agent#readme",
  "bugs": {
    "url": "https://github.com/jgauffin/kiwi-code-agent/issues"
  },
  "keywords": [
    "ai",
    "agent",
    "claude",
    "openai",
    "coding",
    "planning"
  ],
  "engines": {
    "vscode": "^1.100.0",
    "node": ">=22.0.0"
  },
  "categories": [
    "AI",
    "Chat"
  ],
  "main": "./dist/extension.js",
  "activationEvents": [
    "onWebviewPanel:kiwiAgent.chatPanel",
    "onWebviewPanel:kiwiAgent.settingsPanel"
  ],
  "contributes": {
    "viewsContainers": {
      "activitybar": [
        {
          "id": "kiwiAgent",
          "title": "KiwiAgent",
          "icon": "$(hubot)"
        }
      ]

489:    "test": "vitest run",
---
import { defineConfig } from 'vitest/config'

export default defineConfig({
  test: {
    include: ['test/**/*.test.ts'],
    // One worker process per file (the default) spawns 98 processes for this
    // suite; on this machine that reliably starves some of them mid-startup
    // ("Cannot read properties of undefined (reading 'config')", "Vitest
    // failed to find the runner"), failing files at random with no code
    // fault. Reusing workers across files avoids the spawn storm. (Forcing
    // it down to a single worker, or dropping isolation further, was tried
    // and traded this flake for a worse one: jsdom/module state leaking
    // between unrelated test files.)
    isolate: false,
  },
})
